
#include <gtest/gtest.h>
#include "code/Scrambler.h"
#include "misc/BitUtils.h"
#include <iostream>
#include <string>
#include <vector>
#include <bitset>

TEST(test_Scrambler, SingleSequence) {
    // Входная строка (1600 бит)
    std::string input = "";

    // Проверка длины
    ASSERT_EQ(input.length(), 1600) << "Длина входа: " << input.length() << ", ожидается 1600";

    // NCellID = 101 (как в MATLAB)
    uint32_t ncell = 101;

    // Конвертируем строку в биты
    auto bits = BitUtils::stringToBitVector(input);

    // Создаём скрэмблер
    NBIoTScrambler scrambler(bits, ncell, "NPBCH");

    // ========== ОТЛАДОЧНЫЙ ВЫВОД (как в MATLAB) ==========
    std::cout << "\n=== ГЕНЕРАЦИЯ GOLD SEQUENCE ДЛЯ NCellID = " << ncell << " ===\n";

    // Получаем регистры
    auto x1 = scrambler.getX1();
    auto x2 = scrambler.getX2();
    auto gold20 = scrambler.getGoldSequenceFirst20();

    // Вывод x1 (первые 20 бит)
    std::cout << "\n=== РЕГИСТРЫ (первые 20 бит) ===\n";
    std::cout << "x1(1:20):  ";
    for (int i = 0; i < 20; i++) {
        std::cout << (int)x1[i];
    }
    std::cout << "\n";

    std::cout << "x2(1:20):  ";
    for (int i = 0; i < 20; i++) {
        std::cout << (int)x2[i];
    }
    std::cout << "\n";

    // Вывод Gold Sequence (первые 20 бит)
    std::cout << "\n=== GOLD SEQUENCE (первые 20 бит) ===\n";
    std::cout << "goldSeq(1:20): ";
    for (size_t i = 0; i < gold20.size(); i++) {
        std::cout << (int)gold20[i];
    }
    std::cout << "\n";

    // Получаем скремблированные биты
    auto result = scrambler.getScrambledBits();
    std::string result_str = BitUtils::bitVectorToString(result);

    // Проверка длины
    ASSERT_EQ(result_str.length(), 1600) << "Длина выхода: " << result_str.length() << ", ожидается 1600";

    // ========== РЕЗУЛЬТАТ ==========
    std::cout << "\n=== РЕЗУЛЬТАТ ===\n";
    std::cout << "NCellID: " << ncell << "\n";
    std::cout << "Длина входа: " << input.length() << " бит\n";
    std::cout << "Длина выхода: " << result_str.length() << " бит\n";

    // Первые 15 бит
    std::string first15 = result_str.substr(0, 15);
    std::string last15 = result_str.substr(result_str.length() - 15);

    std::cout << "\nПервые 15 бит: " << first15 << "\n";
    std::cout << "Последние 15 бит: " << last15 << "\n";

    // Первые 100 бит для отладки
    std::cout << "\nПервые 100 бит: " << result_str.substr(0, 100) << "\n";

    // Ожидаемые значения (из MATLAB)
    std::string expected_first15 = "110001101101101";
    std::string expected_last15 = "101101100111111";

    // Сравнение
    EXPECT_EQ(first15, expected_first15) << "Первые 15 бит не совпадают";
    EXPECT_EQ(last15, expected_last15) << "Последние 15 бит не совпадают";
}